INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-07', 7, '第7課 听力训练', 'listening/listening-lesson-07.mp3', 184947, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn07-s1', 'listen-07', 1, 'text', '听录音，根据录音中的内容仿照例子写下相应的数字。', 13487, 117420, '弟さんは今、18歳です。', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s1-q1', 'lsn07-s1', 1, '教室に、今何人いますか。＿＿人です。', '[]'::jsonb, '2');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s1-q2', 'lsn07-s1', 2, '吉村さんのお部屋は何階にありますか。＿＿階です。', '[]'::jsonb, '6');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s1-q3', 'lsn07-s1', 3, '長谷川さんには、お姉さんが何人いますか。＿＿人います。', '[]'::jsonb, '1');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s1-q4', 'lsn07-s1', 4, '写真の中の弟さんは何歳ですか。＿＿歳です。', '[]'::jsonb, '5');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l1', 'lsn07-s1', 1, 'A', 13787, 17236, '弟さんは、おいくつですか。', 'A：你弟弟多大了？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l2', 'lsn07-s1', 2, 'B', 18335, 22717, '今大学1年生で、18歳です。', 'B：现在是大学一年级，18岁。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l3', 'lsn07-s1', 3, 'A', 31648, 38323, '教室に、今何人いますか。', 'A：教室里现在有几个人？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l4', 'lsn07-s1', 4, 'B', 39043, 43100, '先生が1人と学生1人います。', 'B：有一位老师和一位学生。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l5', 'lsn07-s1', 5, 'A', 52182, 58451, 'こんにちは。吉村です。', 'A：你好，我是吉村。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l6', 'lsn07-s1', 6, 'B', 59567, 65713, 'あ、吉村さんですね。お部屋は６階にあります。', 'B：啊，是吉村啊。你的房间在6楼。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l7', 'lsn07-s1', 7, 'A', 74615, 81740, '長谷川さんのご家族は何人いますか。', 'A：长谷川家有几口人？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l8', 'lsn07-s1', 8, 'B', 82197, 87913, '５人です。両親と兄と姉がいます。', 'B：5口人。有父母、哥哥和姐姐。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l9', 'lsn07-s1', 9, 'A', 96815, 105041, 'これは小林さんのご家族の写真ですか。', 'A：这是小林家人的照片吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l10', 'lsn07-s1', 10, 'B', 106557, 107187, 'はい、弟です。', 'B：是的，是我弟弟。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l11', 'lsn07-s1', 11, 'A', 107959, 111149, 'へえ、弟さん、今、何歳ですか。', 'A：哦，你弟弟现在多大？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s1-l12', 'lsn07-s1', 12, 'B', 111810, 116720, 'そうですね、今、６歳です。これは去年の写真です。', 'B：这个嘛，现在6岁。这是去年的照片。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn07-s2', 'listen-07', 2, 'choice', '听录音，根据录音中的内容，将正确答案填在括号中。背景：长谷川和小王在谈论自己的家庭成员。', 137278, 182260, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s2-q1', 'lsn07-s2', 1, '王さんには兄弟がいますか。', '[{"key":"a","text":"はい、います。"},{"key":"b","text":"いいえ、いません。"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s2-q2', 'lsn07-s2', 2, '長谷川さんには兄弟が＿＿います。', '[{"key":"a","text":"ひとり"},{"key":"b","text":"ふたり"}]'::jsonb, 'a');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s2-q3', 'lsn07-s2', 3, '長谷川さんのお姉さんは今＿＿にいますか。', '[{"key":"a","text":"東京"},{"key":"b","text":"大阪"},{"key":"c","text":"北京"}]'::jsonb, 'b');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn07-s2-q4', 'lsn07-s2', 4, '長谷川さんのお姉さんは今＿＿歳です。', '[{"key":"a","text":"14"},{"key":"b","text":"20"},{"key":"c","text":"24"}]'::jsonb, 'c');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l1', 'lsn07-s2', 1, '長谷川', 137578, 139858, '王さんは何人家族ですか。', '长谷川：小王家有几口人？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l2', 'lsn07-s2', 2, '王', 140547, 143795, '３人です。父と、母と私です。', '王：3口人。爸爸、妈妈和我。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l3', 'lsn07-s2', 3, '長谷川', 145144, 149087, 'へえ、兄弟はいませんか。', '长谷川：哦，没有兄弟姐妹吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l4', 'lsn07-s2', 4, '王', 149088, 154047, 'はい、いません。私だけです。長谷川さんは？', '王：是的，没有。就我一个。长谷川你呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l5', 'lsn07-s2', 5, '長谷川', 154625, 156612, '私は姉がいます。', '长谷川：我有个姐姐。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l6', 'lsn07-s2', 6, '王', 157679, 160019, 'へえ、写真はありますか。', '王：哦，有照片吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l7', 'lsn07-s2', 7, '長谷川', 160563, 164188, 'ありますよ。これは姉です。', '长谷川：有啊。这就是我姐姐。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l8', 'lsn07-s2', 8, '王', 164189, 166185, '長谷川さんとそっくりですね。', '王：和你长得真像。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l9', 'lsn07-s2', 9, '長谷川', 166432, 169452, 'そうですか。姉はいま会社員で、大阪にいます。', '长谷川：是吗。姐姐现在是公司职员，在大阪。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l10', 'lsn07-s2', 10, '王', 169508, 172262, 'へえ、お姉さんは今、おいくつですか。', '王：哦，你姐姐现在多大？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l11', 'lsn07-s2', 11, '長谷川', 172818, 174964, '２４歳です。', '长谷川：24岁。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l12', 'lsn07-s2', 12, '王', 175219, 177644, 'じゃ、去年はまだ大学生でしたか。', '王：那去年她还是大学生吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn07-s2-l13', 'lsn07-s2', 13, '長谷川', 178568, 181560, 'そうです。まだ新入社員です。', '长谷川：是的。还是新员工。');
